// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.testingimport com.roshan.persona.common.CorrelationIdimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.ExperimentalCoroutinesApiimport kotlinx.coroutines.test.StandardTestDispatcherimport kotlinx.coroutines.test.TestDispatcherimport kotlinx.coroutines.test.resetMainimport kotlinx.coroutines.test.setMainimport org.junit.rules.TestWatcherimport org.junit.runner.Description/** * JUnit rule that sets [Dispatchers.setMain] to a test dispatcher, so tests * using `withContext(Dispatchers.Main)` are deterministic. * * Usage: * ```kotlin * @get:Rule val mainDispatcherRule = MainDispatcherRule() * * @Test fun `test thing on main thread`() = runTest(mainDispatcherRule.dispatcher) { *     // ... * } * ``` */@OptIn(ExperimentalCoroutinesApi::class)class MainDispatcherRule(    val dispatcher: TestDispatcher = StandardTestDispatcher(),) : TestWatcher() {    override fun starting(description: Description) {        Dispatchers.setMain(dispatcher)    }    override fun finished(description: Description) {        Dispatchers.resetMain()    }}/** * Test fixture: a stable [CorrelationId] for deterministic tests. */val TEST_CORRELATION_ID: CorrelationId = CorrelationId("00000000-0000-0000-0000-000000000000")